INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132478, 'ruRU', '', 'Я спросил его, сколько он дал адмиралу на лапу, чтобы это устроить, и он рассказал мне свой секрет...', 24330),
(132479, 'ruRU', '', 'Он получил его "на парусах" (то есть со скидкой)!', 24330),
(132480, 'ruRU', '', 'Это одна из тех головоломок для мозгов...', 24330),
(132481, 'ruRU', '', 'Что имеет шесть ног, шесть рук и шесть глаз?', 24330),
(132482, 'ruRU', '', 'Шесть пиратов!', 24330),
(132483, 'ruRU', '', 'Вы все знаете безумного контр-адмирала Смехопалуба, да?', 24330),
(132484, 'ruRU', '', 'Знали вы, что он однажды использовал свои гномские приспособления, чтобы соединить попугая и акулу в идеального пиратского спутника?', 24330),
(132485, 'ruRU', '', 'Сработало отлично... пока оно не заболтало ему уши до смерти!', 24330),
(132486, 'ruRU', '', 'Так что не так с сундуками сокровищ в наши дни? Они такие дорогие и блестящие...', 24330),
(132487, 'ruRU', '', 'Такое чувство, что мы сами хотим, чтобы их нашли! Вся эта блестящая золотая отделка и замки, усыпанные самоцветами...', 24330),
(132488, 'ruRU', '', 'Это как, мы храним сокровище СНАРУЖИ или ВНУТРИ? А, точно?', 24330),
(132530, 'ruRU', '', 'Тут написано, что их лидер находится на одном из тех плавающих дисков над нами. Время пойти и прикончить его!', 24330),
(132567, 'ruRU', '', 'Тебе нужно поработать над своими движениями, $p! Мы будем устраивать танцевальные вечеринки в аукционных домах Штормграда и Оргриммара!', 24330),
(132568, 'ruRU', '', 'Мы захватим аукционные дома Штормграда и Оргриммара для танцевальной вечеринки! Лучше бы тебе там быть!', 24330),
(132569, 'ruRU', '', 'Все танцуют! Мы захватили аукционные дома Штормграда и Оргриммара для танцевальной вечеринки!', 24330),
(132570, 'ruRU', '', 'Приходи и принеси свой хороший настрой на наши танцевальные вечеринки в аукционных домах Штормграда и Оргриммара!', 24330),
(132578, 'ruRU', '', 'Думаю, нам стоит начать расследование с разговора с каким-нибудь бронзовым драконом.', 24330),
(132585, 'ruRU', '', 'Как я могу помочь тебе?', 24330),
(132586, 'ruRU', '', 'Да, мы заняты. Обычно к нам забредает один-два случайных вурдалака в день, но сегодня они напали в количестве, которого мы не видели почти десять лет.', 24330),
(132587, 'ruRU', '', 'Да? Чем я могу тебе помочь?', 24330),
(132588, 'ruRU', '', 'Да, были. Сновидцы были неспокойны. Это было... невыносимо.', 24330),
(132658, 'ruRU', '', '|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|tКапитан Ятэ Лунный Удар прицеливается |cFFFF0000|Hspell:236304|h[Бесплотным выстрелом]|h|r!', 24330),
(132659, 'ruRU', '', '|TInterface\\Icons\\ABILITY_DRUID_ECLIPSE.BLP:20|tЖрица Луношпиль применила |cFFFF0000|Hspell:233263|h[Объятия затмения]|h|r!', 24330),
(132660, 'ruRU', '', '|TInterface\\Icons\\ABILITY_UPGRADEMOONGLAIVE.BLP:20|tОхотница Каспариан применяет |cFFFF0000|Hspell:236480|h[Шторм клинков]|h|r!', 24330),
(132729, 'ruRU', '', 'С силой печати мы можем отправиться прямо в Чертог Аватары.', 24330),
(132738, 'ruRU', '', 'Глянь-ка на время! Осталось всего около десяти минут...', 24330),
(132739, 'ruRU', '', 'Осталось пять минут. Думаешь, мы успеем вовремя?', 24330),
(132740, 'ruRU', '', 'Осталась одна минута. Немного впритык, да?', 24330),
(132741, 'ruRU', '', 'Я чувствую сокровище рядом.', 24330),
(132742, 'ruRU', '', 'Чувствуешь? Где-то здесь есть сокровище.', 24330),
(132743, 'ruRU', '', 'Ни с места!', 24330),
(132744, 'ruRU', '', 'Стоять на месте!', 24330),
(132746, 'ruRU', '', 'В другом углу - голем с притягательной личностью. Берегись, этот голем сейчас тебя отклункает!', 24330),
(132812, 'ruRU', '', 'Что это вообще, чёрт возьми, было?', 24330),
(133116, 'ruRU', '', 'Круг Кенария не может сидеть сложа руки, пока солдаты Орды и Альянса бессмысленно убивают друг друга. Если я могу подарить утешение раненым солдатам, я буду довольна.', 24330),
(133118, 'ruRU', '', 'Тут... тут написано, что ты несёшь приказы от самого Хранителя Ремула! Что ж, хорошо, какие твои приказы, $n?', 24330),
(133121, 'ruRU', '', 'Хроми нужна наша помощь? Конечно. Мы отвлечём пушки, чтобы она могла улететь в безопасности..', 24330),
(133163, 'ruRU', '', 'Я значительно замедлила время, чтобы мы могли подготовиться, не теряя ни секунды драгоценного времени.$b$bДай мне знать, когда будешь готов идти!', 24330),
(133227, 'ruRU', '', 'Смерть идёт за тобой, маленький дракон...', 24330),
(133235, 'ruRU', '', 'Умный дракон. Я уже поймала тебя раз, и сделаю это снова!', 24330);
